package com.transiva.app;
import android.content.Context; import android.content.SharedPreferences; import android.util.Base64; import java.nio.charset.StandardCharsets; import java.security.KeyStore; import javax.crypto.Cipher; import javax.crypto.KeyGenerator; import javax.crypto.SecretKey; import javax.crypto.spec.GCMParameterSpec; import android.security.keystore.KeyGenParameterSpec; import android.security.keystore.KeyProperties;
public final class SecureTokenStore { private static final String A="transiva_driver_session_key",P="transiva_driver_secure",K="token"; private SecureTokenStore(){}
 public static void save(Context c,String value){try{if(value==null||value.isEmpty()){clear(c);return;}Cipher x=Cipher.getInstance("AES/GCM/NoPadding");x.init(Cipher.ENCRYPT_MODE,key());String out=Base64.encodeToString(x.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(x.doFinal(value.getBytes(StandardCharsets.UTF_8)),Base64.NO_WRAP);c.getSharedPreferences(P,0).edit().putString(K,out).apply();}catch(Throwable ignored){}}
 public static String read(Context c){try{String v=c.getSharedPreferences(P,0).getString(K,"");if(v.isEmpty())return"";String[] a=v.split(":",2);Cipher x=Cipher.getInstance("AES/GCM/NoPadding");x.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(a[0],Base64.NO_WRAP)));return new String(x.doFinal(Base64.decode(a[1],Base64.NO_WRAP)),StandardCharsets.UTF_8);}catch(Throwable e){return"";}}
 public static void clear(Context c){c.getSharedPreferences(P,0).edit().clear().apply();}
 private static SecretKey key()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias(A)){KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(A,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return((KeyStore.SecretKeyEntry)ks.getEntry(A,null)).getSecretKey();}}
